1	import java.util.List;
2	import java.util.ArrayList;
3	import java.util.Random;
4	import java.util.Iterator;
5	
6	
7	
8	/**
9	    * Interface method required for lambda expression which initalises an animal of any type 
10	*/
11	interface CreateAnimal {
12	
13	    /**
14	    * Function required for initalisating any animal
15	    * @param loc required location for initalisation of animal
16	    * @return animal, the initalised animal 
17	    */
18	    Animal initialise(Location loc);
19	}
20	
21	/**
22	 * A class representing shared characteristics of animals.
23	 *
24	 * @version 2s
25	 */
26	public abstract class Animal extends Locatable implements Simulatable, Breedable, Displayable, Infectable
27	{
28	    // Whether the animal is alive or not.
29	    private boolean alive;
30	
31	    //The gender of the animal
32	    protected Gender gender;
33	
34	
35	    //Storage for a disease of the animal. Is set to null as animals are not (in this sim) born with diseases
36	    protected Disease currentDisease = null; 
37	
38	
39	    //Random for the calculation of probabilities. 
40	    protected static final Random rand = Randomizer.getRandom();
41	
42	    // The animals's age.
43	    protected int age;
44	    // The animals's food level, which is increased by eating rabbits.
45	    protected int foodLevel;
46	    
47	    /**
48	     * Create a new animal at location in field.
49	     * 
50	     * @param field The field currently occupied.
51	     * @param location The location within the field.
52	     */
53	    public Animal(Field field, Location location)
54	    {
55	        //Initalise the location 
56	        super(field, location);
57	        alive = true;
58	        gender = rand.nextInt(2) == 0 ? Gender.MALE : Gender.FEMALE; //Create a gender, with a 50% chance of either. 
59	    }
60	    
61	
62	    /**
63	     * Check whether the animal is alive or not.
64	     * @return true if the animal is still alive.
65	     */
66	    public boolean isAlive()
67	    {
68	        return alive;
69	    }
70	
71	    /**
72	     * Get the gender of the animal 
73	     * @return gender 
74	     */
75	    public Gender getGender () {
76	        return gender;
77	    }
78	
79	
80	    /**
81	     * This amounts to an exposurure of a particular disease. If the animal meets the required probability, it will give the animal the disease
82	     * @param disease the disease that the animal has been exposed
83	     */
84	    public void giveDisease(Disease disease) {
85	        //Check if the disease exists, if the probability is high enough and the animal is not already diseased
86	        if (disease != null && rand.nextDouble () <= disease.getR0() && currentDisease == null){
87	            currentDisease = disease;
88	        }
89	    }
90	
91	    /**
92	     * Force a disease on an animal without probability requirements. 
93	     * @param disease the disease to give the animal
94	     */
95	    public void forceDisease(Disease disease) {
96	        currentDisease = disease;
97	    }
98	
99	
100	    /**
101	     * Get the disease of the animal 
102	     * @return a disease if the animal has one, if not just null. 
103	     */
104	    public Disease getDisease() {
105	        return currentDisease;
106	    }
107	
108	
109	
110	    /**
111	     * Indicate that the animal is no longer alive.
112	     * It is removed from the field.
113	     */
114	    public void setDead()
115	    {
116	        alive = false;
117	        removeFromField();//Call the super (Locatable) removeFromField which removes the animal from the field 
118	    }
119	
120	
121	    /**
122	     * fetch all the potential mates (of the same animal type) for an animal. 
123	     * @param type the type of animal to get the mates for 
124	     * @return a list of all potential mates 
125	     */
126	    protected List<Animal> getPotentialMates(Class type) {
127	        Field field = getField();
128	        ArrayList<Animal> potentialMates = new ArrayList<Animal>();
129	        List<Object> nearAnimals = field.getItemOfTypeNear(type, getLocation());
130	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
131	        for(Object i : nearAnimals) {
132	            var potentialMate = (Animal)type.cast(i);
133	
134	            if (potentialMate.canBreed(getGender().invert()) && canBreed(getGender())) {
135	                potentialMates.add(potentialMate);
136	
137	            }
138	        }
139	        return potentialMates;
140	    }
141	
142	    
143	    /**
144	     * Generate a number representing the number of births,
145	     * if it can breed.
146	     * @return The number of births (may be zero).
147	     */
148	    protected int breed(int currentNumberOfAnimal)
149	    {
150	        int births = 0;
151	
152	        // double counterCyclical = -(1 / (1 + Math.pow(Math.E, -((currentNumberOfAnimal / 20 - 40))))) + getBreedingProbability();//See report for formula
153	
154	        double counterCyclical = (2 * getBreedingProbability()) / (1 + Math.pow(Math.E, (currentNumberOfAnimal / 50) - 300));
155	
156	        // double breedingProbability = (getBreedingProbability() + counteCyclical) / 2; //Counter cyclical calculations
157	
158	        if(rand.nextDouble() <= counterCyclical) {
159	            births = rand.nextInt(getMaxLitterSize()) + 1;
160	        }
161	        return births;
162	    }
163	
164	    /**
165	     * Make this an animal more hungry. This could result in the animal's death.
166	     */
167	    protected void incrementHunger()
168	    {
169	        foodLevel--;
170	        if(foodLevel <= 0) {
171	            setDead();
172	        }
173	    }
174	
175	
176	    /**
177	     * Make this animal older. This could result in the animal's death
178	     * @param maxAge the age at which the animal should die.
179	     */
180	    protected void incrementAge(int maxAge)
181	    {
182	        age++;
183	        if(age > maxAge) {
184	            setDead();
185	
186	        }
187	    }
188	
189	
190	    /**
191	     * This will create the new animals if the animal is a female, is near to a male and the required probability is correct
192	     * @param animalType the type of the animal that this animal should breed with 
193	     * @param newAnimals the list which will contian the new animlas 
194	     * @param animalCreator a function of type (Location) -> Animal (conforms to CreateAnimal). This function will create the animals
195	     */
196	    protected void giveBirth(Counter numberOfAnimals, Class animalType, List<Simulatable> newAnimals, CreateAnimal animalCreator)
197	    {
198	        // New foxes are born into adjacent locations.
199	        // Get a list of adjacent free locations.
200	        Field field = getField();
201	        List <Animal> potentialMates = getPotentialMates(animalType);
202	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
203	        for (Animal i : potentialMates) {
204	            int births = breed(numberOfAnimals.getCount());
205	            for(int b = 0; b < births && free.size() > 0; b++) {
206	                Location loc = free.remove(0);
207	                // Hawk young = new Hawk(false, field, loc);
208	                Simulatable young = animalCreator.initialise(loc);
209	                newAnimals.add(young);
210	            }
211	        }
212	    }
213	
214	
215	    /**
216	     * Look for food sources adjacent to the current location.
217	     * Only the first food source is eaten.
218	     * @return Where food was found, or null if it wasn't.
219	     */
220	    protected Location findFood(List<Class> eats)
221	    {
222	        Field field = getField();
223	        List<Location> adjacent = field.adjacentLocations(getLocation());
224	        Iterator<Location> it = adjacent.iterator();
225	        while(it.hasNext()) {
226	            Location where = it.next();
227	            Object animal = field.getObjectAt(where);
228	            if(animal != null && eats.contains(animal.getClass())) {
229	                var prey = (Simulatable & Eatable) animal;
230	                if(prey.isAlive()) { 
231	                    prey.setDead();
232	                    foodLevel = prey.getFoodValue();
233	                    return where;
234	                }
235	            }
236	        }
237	        return null;
238	    }
239	
240	
241	    /**
242	     * Move to a new location. If there is a food source nearby, move to 
243	     * that location, if not, move to a random location. 
244	     * @param eats a list of what this animal eats
245	     * @param maxFoodHunger an int value of the max amount an animal can eat
246	     */
247	    protected void moveToNewLocation(List<Class> eats, int maxFoodHunger) {
248	        // Move towards a source of food if found and needed.
249	        Location newLocation = foodLevel < maxFoodHunger ? findFood(eats) : null;
250	       
251	        
252	        if(newLocation == null ) { 
253	            // No food found - try to move to a free location.
254	            newLocation = getField().freeAdjacentLocation(getLocation());
255	        }
256	        // See if it was possible to move.
257	        if(newLocation != null) {
258	            setLocation(newLocation);
259	        }
260	        else {
261	            // Overcrowding.
262	            setDead();
263	        }
264	    }
265	
266	
267	    /**
268	     * Expose all nearby animals to the disease this current animal has. 
269	    */
270	    protected void giveNearbyAnimalsDisease(){
271	        List<Object> nearAnimals = getField().getItemOfTypeNear(Animal.class, getLocation());
272	        for(Object i : nearAnimals) {
273	            if (i instanceof Animal) {
274	                Animal otherAnimal = (Animal)i;
275	                otherAnimal.giveDisease(getDisease());
276	            }
277	        }
278	    }
279	}
