7	/**
8	 * A simple model of a rat.
9	 * Rats age, move, breed, and die.
10	 * 
11	 * @version 0.0.1
12	 */
13	public class Rat extends Animal implements Eatable
14	{
15	
16		/*
17			Population Control variables
18		*/
19		public static PopulationControls POPULATION_CONTROLS = new PopulationControls(
20			5, //Breeding age
21			40, // Maximum age
22			4, // Maximum litter size
23			50, //Maximum hunger (how full a mouse can be)
24			20, // Initial hunger
25			0.27, // Breeding probability
26			0.08// Creation probability
27		); 
28	
29	
30		
31		private static final int FOOD_VALUE = 9;//This is the food value of the rat (how much it will feed its preadtor) 
32	
33		//An array containing what all Rats eat
34		private static final List<Class> EATS = new ArrayList<Class>(){{
35			add(Grass.class);
36		}};
37	
38	
39		
40	
41		/**
42		 * Create a new rat. A rat may be created with age
43		 * zero (a new born) or with a random age.
44		 * 
45		 * @param randomAge If true, the rat will have a random age.
46		 * @param field The field currently occupied.
47		 * @param location The location within the field.
48		 */
49		public Rat(boolean randomAge, Field field, Location location)
50		{
51			super(field, location);//Initalise the super class
52			age = 0;
53			foodLevel = POPULATION_CONTROLS.getInitialHunger();
54			if(randomAge) {
55				age = rand.nextInt(POPULATION_CONTROLS.getMaxAge());
56			}
57	
58		}
59	
60	
61		/**
62		 * This is what the rabbit does most of the time - it runs 
63		 * around. Sometimes it will breed or die of old age.
64		 * @param newRabbits A list to return newly born rabbits.
65		 * @param currentState is the current state of the world around the rat (the weather, time etc)
66		 */
67		public void act(List<Simulatable> newAnimals, SimulatorState currentState)
68		{
69			incrementAge(POPULATION_CONTROLS.getMaxAge());
70			Field f = getField();//Get the field the rat is in
71			if(rand.nextDouble() <= currentState.getAggregatedProbabilityReduction()) {
72				incrementHunger();
73				if (isAlive()) {
74					giveNearbyAnimalsDisease();
75	
76					Counter numberOfAnimal = currentState.getCurrentStats(Rat.class);
77					giveBirth(numberOfAnimal, Rat.class, newAnimals, (Location loc) -> new Rat(false, f, loc));
78	
79					//Implement the effects of the disease
80					Disease currentDisease = getDisease();
81					if (currentDisease != null) {
82						foodLevel -= currentDisease.getHungerEffect();
83						age -= currentDisease.getAgeEffect();
84					}
85	
86					//Move to a new location based on if there is grass there
87					moveToNewLocation(EATS, POPULATION_CONTROLS.getMaxHunger());
88				}
89			}
90		}
91		
92		/**
93		 * Implementation of eatable 
94		 * @return the food value of a rat
95		 */
96		public int getFoodValue (){
97			return FOOD_VALUE;
98		}
99	
100		/**
101		 * implementation of displayable 
102		 * @return the color of a rat
103		 */ 
104		public Color getColor() {
105			return Color.YELLOW;
106		}
107	
108		/**
109		 * Implementaion of displayable 
110		 * @return the border color of a rat
111		 */
112		public Color getBorderColor() {
113			return getDisease() == null ? null : Color.PINK;
114		}
115	
116		/**
117		 * Implementaion of breedable
118		 * @return the age at which rats can start breeding 
119		 */
120		public int getBreedingAge () {
121			return POPULATION_CONTROLS.getBreedingAge();
122		}
123	
124		/**
125		 * Implementaion of breedable
126		 * @return the age of this rat
127		 */
128		public int getAge () {
129			return age;
130		}
131	
132		/**
133		 * Implementaion of breedable
134		 * @return the breeding probability of rats
135		 */
136		public double getBreedingProbability() {
137			return POPULATION_CONTROLS.getBreedingProbability();
138		}
139	
140	
141		/**
142		 * Implementaion of breedable
143		 * @return the maximum litter size of rats
144		 */
145		public int getMaxLitterSize() {
146			return POPULATION_CONTROLS.getMaxLitterSize();
147		}
148	}

