15		// Characteristics shared by all mouses (class variables).
16	
17		/*
18			Population Control variables
19		*/
20		public static PopulationControls POPULATION_CONTROLS = new PopulationControls(
21			5, //Breeding age
22			40, // Maximum age
23			4, // Maximum litter size
24			50, //Maximum hunger (how full a mouse can be)
25			20, // Initial hunger
26			0.36, // Breeding probability
27			0.08// Creation probability
