29	
30		// public static PopulationControls POPULATION_CONTROLS = new PopulationControls(
31		// 	5, //Breeding age
32		// 	40, // Maximum age
33		// 	4, // Maximum litter size
34		// 	50, //Maximum hunger (how full a mouse can be)
35		// 	20, // Initial hunger
36		// 	0.12, // Breeding probability
