56		 */
57		public Mouse(boolean randomAge, Field field, Location location)
58		{
59			super(field, location);
60			age = 0;
61			foodLevel = POPULATION_CONTROLS.getInitialHunger();
62			if(randomAge) {
63				age = rand.nextInt(POPULATION_CONTROLS.getMaxAge());
64			}
65	
66		}
67		
68		/**
69		 * This is what the mouse does most of the time - it runs 
70		 * around. Sometimes it will breed or die of old age.
71		 * @param newMouses A list to return newly born mouses.
72		 * @param currentState is the current state of the world around the fox (the weather, time etc)
73		 */
74		public void act(List<Simulatable> newMouses, SimulatorState currentState)
75		{
76			incrementAge(POPULATION_CONTROLS.getMaxAge());//Increment the age of the mouse (potentially killing it )
77			Field f = getField();//Get the field that the mouse is in 
78	
79			//Probability reduction. If the generated probability is lower then the reductions then the mouse will act
80			if(rand.nextDouble() <= currentState.getAggregatedProbabilityReduction()) {
81				incrementHunger();//Only if it acts will it reduce hunger
82				if (isAlive()) {
83	
84					giveNearbyAnimalsDisease();
85	
86					Counter numberOfAnimal = currentState.getCurrentStats(Mouse.class);
87					giveBirth(numberOfAnimal, Mouse.class, newMouses, (Location loc) -> new Mouse(false, f, loc));
88	
89					//Implement the effects of the disease 
90					Disease currentDisease = getDisease();
91					if (currentDisease != null) {
92						foodLevel -= currentDisease.getHungerEffect();
93						age -= currentDisease.getAgeEffect();
94					}
95	
96					moveToNewLocation(EATS, POPULATION_CONTROLS.getMaxHunger());
97	
98				}
99			}
100		}
