7	/**
8	 * A simple model of a Racoon.
9	 * Racoones age, move, eat rabbits, and die.
10	 *
11	 * @version 2016.02.29 (2)
12	 */
13	public class Racoon extends Animal
14	{
15	    // Characteristics shared by all Racoones (class variables).
16	    
17	
18	    /*
19	        Population Control variables
20	    */
21	
22	    public static PopulationControls POPULATION_CONTROLS = new PopulationControls(
23	        15, //Breeding age 
24	        150, //Maxium age
25	        2, //Maximum litter size
26	        30, //Maximum hunger
27	        9, // Initial hunger
28	        0.26, //Breeding probability
29	        0.026 // creation probability
30	    );  
31	    // public static PopulationControls POPULATION_CONTROLS = new PopulationControls(
32	    //     15, //Breeding age 
33	    //     150, //Maxium age
34	    //     2, //Maximum litter size
35	    //     30, //Maximum hunger
36	    //     9, // Initial hunger
37	    //     0.2, //Breeding probability
38	    //     0.025 // creation probability
39	    // ); 
40	
41	
42	    //List of all animals that the Racoon eats
43	    private static final List<Class> EATS = new ArrayList<Class>(){{
44	        add(Mouse.class);
45	        add(Squirrel.class);
46	    }};
47	
48	 
49	
50	    /**
51	     * Create a Racoon. A Racoon can be created as a new born (age zero
52	     * and not hungry) or with a random age and food level.
53	     * 
54	     * @param randomAge If true, the Racoon will have random age and hunger level.
55	     * @param field The field currently occupied.
56	     * @param location The location within the field.
57	     */
58	    public Racoon(boolean randomAge, Field field, Location location)
59	    {
60	        super(field, location);
61	        if(randomAge) {
62	            age = rand.nextInt(POPULATION_CONTROLS.getMaxAge());
63	            foodLevel = rand.nextInt(POPULATION_CONTROLS.getInitialHunger());
64	        } else {
65	            age = 0;
66	            foodLevel = POPULATION_CONTROLS.getInitialHunger();
67	        }
68	    }
69	    
70	    /**
71	     * This is what the Racoon does most of the time: it hunts for
72	     * rabbits. In the process, it might breed, die of hunger,
73	     * or die of old age.
74	     * @param newRacoones A list to return newly born Racoones.
75	     * @param currentState is the current state of the world around the Racoon (the weather, time etc)
76	     */
77	    public void act(List<Simulatable> newRacoones, SimulatorState currentState)
78	    {
79	        incrementAge(POPULATION_CONTROLS.getMaxAge());
80	        Field f = getField();
81	        if (rand.nextDouble() <= currentState.getAggregatedProbabilityReduction()) {
82	            incrementHunger();     
83	            if(isAlive() ) {
84	
85	                Counter numberOfAnimal = currentState.getCurrentStats(Racoon.class);
86	                giveBirth(numberOfAnimal, Racoon.class, newRacoones, (Location loc) -> new Racoon(false, f, loc));
87	
88	                giveNearbyAnimalsDisease();
89	
90	                Disease currentDisease = getDisease();
91	                if (currentDisease != null) {
92	                    foodLevel -= currentDisease.getHungerEffect();
93	                    age -= currentDisease.getAgeEffect();
94	                }
95	                    
96	                moveToNewLocation(EATS, POPULATION_CONTROLS.getMaxHunger());
97	            }
98	        }
99	    }
100	
101	    public Color getColor() {
102	        return Color.ORANGE;
103	    }
104	
105	    public Color getBorderColor() {
106	        return getDisease() == null ? null : Color.PINK;
107	    }
108	
109	    public Gender getGender () {
110	        return gender;
111	    }
112	
113	    public int getBreedingAge () {
114	        return POPULATION_CONTROLS.getBreedingAge();
115	    }
116	
117	    public int getAge () {
118	        return age;
119	    }
120	
121	    public double getBreedingProbability() {
122	        return POPULATION_CONTROLS.getBreedingProbability();
123	    }
124	
125	    public int getMaxLitterSize() {
126	        return POPULATION_CONTROLS.getMaxLitterSize();
127	    }
128	}
