7	/**
8	 * model of a hawk
9	 * Foxes age, move, eat, and die.
10	 * 
11	 * @version 0.2.1
12	 */
13	public class Hawk extends Animal
14	{
15	    // Characteristics shared by all hawks.
16	    /*
17	        Population Control variables
18	    */
19	    public static PopulationControls POPULATION_CONTROLS = new PopulationControls(
20	        15, //Breeding age 
21	        150, //Maxium age
22	        2, //Maximum litter size
