151	
152	        // double counterCyclical = -(1 / (1 + Math.pow(Math.E, -((currentNumberOfAnimal / 20 - 40))))) + getBreedingProbability();//See report for formula
153	
154	        double counterCyclical = (2 * getBreedingProbability()) / (1 + Math.pow(Math.E, (currentNumberOfAnimal / 50) - 300));
155	
156	        // double breedingProbability = (getBreedingProbability() + counteCyclical) / 2; //Counter cyclical calculations
