221	    {
222	        Field field = getField();
223	        List<Location> adjacent = field.adjacentLocations(getLocation());
224	        Iterator<Location> it = adjacent.iterator();
225	        while(it.hasNext()) {
226	            Location where = it.next();
227	            Object animal = field.getObjectAt(where);
228	            if(animal != null && eats.contains(animal.getClass())) {
229	                var prey = (Simulatable & Eatable) animal;
230	                if(prey.isAlive()) { 
231	                    prey.setDead();
232	                    foodLevel = prey.getFoodValue();
233	                    return where;
234	                }
235	            }
236	        }
237	        return null;
